// Verificar la firma del disparo manual
//
// ════════════════════════════════════════════════════════════════════
//  Sin este nodo, la URL del webhook ERA la única protección: cualquiera
//  que la conociera podía hacer un POST vacío y provocar el envío de los
//  diez correos, saltándose el límite de 10 minutos —que vive en la
//  aplicación, no aquí—. La aplicación ya firmaba la petición; lo que
//  faltaba era que alguien mirase esa firma.
// ════════════════════════════════════════════════════════════════════
//
// Es la misma comprobación que hace `verificar()` en packages/core/src/hmac.ts,
// en el mismo orden y con las mismas tres defensas (TECHNICAL_SPEC §8, capa 3):
//
//   1. Firma HMAC-SHA256 sobre `${timestamp}.${nonce}.${cuerpoCrudo}`,
//      comparada en TIEMPO CONSTANTE. Nunca con `===`.
//   2. Ventana de 5 minutos: una petición capturada caduca enseguida.
//   3. Nonce de un solo uso: dentro de la ventana tampoco puede reenviarse.
//
// Cualquier fallo LANZA. La ejecución se detiene aquí y no sale ningún correo.
//
// ── Requisito del nodo Webhook ────────────────────────────────────────
// «Raw Body» tiene que estar activado en el nodo «Webhook manual». La firma
// cubre los BYTES EXACTOS que se enviaron: si n8n interpretara el JSON y lo
// volviera a serializar, el orden de las claves o el espaciado podrían cambiar
// y la firma dejaría de cuadrar aunque el contenido fuera idéntico.
// Con «Raw Body», n8n deja el cuerpo en `binary.data.data`, en base64.

const cripto = obtenerCripto();

const VENTANA_SEGUNDOS = 300; // 5 minutos
const NONCE_VIDA_MS = 10 * 60 * 1000; // 10 minutos

const secreto = $vars.N8N_SHARED_SECRET;
if (!secreto) throw new Error('Falta la variable N8N_SHARED_SECRET en n8n (Settings → Variables).');

const entrada = $input.first();
const cabeceras = entrada.json?.headers ?? {};

// Node pasa los nombres de cabecera en minúsculas.
const ts = cabeceras['x-crm123-timestamp'];
const nonce = cabeceras['x-crm123-nonce'];
const recibida = cabeceras['x-crm123-signature'];

if (!ts || !nonce || !recibida) {
  throw new Error('Disparo rechazado: faltan las cabeceras de firma.');
}

const base64 = entrada.binary?.data?.data;
if (typeof base64 !== 'string') {
  throw new Error(
    'Disparo rechazado: no llega el cuerpo crudo. ' +
      'Activa la opción «Raw Body» en el nodo «Webhook manual».',
  );
}

const cuerpoCrudo =
  typeof Buffer !== 'undefined'
    ? Buffer.from(base64, 'base64').toString('utf8')
    : new TextDecoder().decode(Uint8Array.from(atob(base64), (c) => c.charCodeAt(0)));

// ── Defensa 2 · Ventana de 5 minutos ──────────────────────────────────
const edad = Math.abs(Date.now() / 1000 - Number(ts));
if (!Number.isFinite(edad) || edad > VENTANA_SEGUNDOS) {
  throw new Error('Disparo rechazado: la petición está fuera de la ventana de 5 minutos.');
}

// ── Defensa 1 · Firma, comparada en tiempo constante ──────────────────
// `cripto.subtle.verify` compara internamente sin cortocircuito. Comparar las
// cadenas con `===` se detendría en el primer carácter distinto, y esa
// diferencia de microsegundos permite adivinar la firma byte a byte
// (CLAUDE.md regla 9).
const hex = String(recibida).replace(/^sha256=/, '');
if (!/^[0-9a-f]{64}$/.test(hex)) {
  throw new Error('Disparo rechazado: firma inválida.');
}

const codificador = new TextEncoder();
const clave = await cripto.subtle.importKey(
  'raw',
  codificador.encode(secreto),
  { name: 'HMAC', hash: 'SHA-256' },
  false,
  ['verify'],
);

const bytes = new Uint8Array(hex.match(/../g).map((h) => parseInt(h, 16)));
const valida = await cripto.subtle.verify(
  'HMAC',
  clave,
  bytes,
  codificador.encode(`${ts}.${nonce}.${cuerpoCrudo}`),
);

if (!valida) throw new Error('Disparo rechazado: firma inválida.');

// ── Defensa 3 · Nonce de un solo uso ──────────────────────────────────
// Se consume DESPUÉS de validar la firma: si se consumiera antes, cualquiera
// podría quemar nonces ajenos mandando basura.
//
// `$getWorkflowStaticData` persiste entre ejecuciones del flujo, así que no
// hace falta base de datos —y no la habría: este flujo no toca Postgres—.
//
// ⚠ LIMITACIÓN CONOCIDA, la misma que ya está anotada en hmac.ts: los datos
// estáticos solo se guardan en ejecuciones de PRODUCCIÓN de un flujo activo,
// y n8n advierte de que pueden comportarse mal con mucha frecuencia de
// ejecución. Aquí son dos disparos al día, así que sobra. Las otras dos
// defensas siguen en pie pase lo que pase.
const estado = $getWorkflowStaticData('global');
const ahora = Date.now();

if (!estado.noncesUsados) estado.noncesUsados = {};
for (const [usado, expira] of Object.entries(estado.noncesUsados)) {
  if (expira <= ahora) delete estado.noncesUsados[usado];
}

if (estado.noncesUsados[nonce]) {
  throw new Error('Disparo rechazado: este nonce ya se usó (reenvío).');
}
estado.noncesUsados[nonce] = ahora + NONCE_VIDA_MS;

// El cuerpo se interpreta solo DESPUÉS de verificarlo.
let cuerpo;
try {
  cuerpo = JSON.parse(cuerpoCrudo);
} catch {
  throw new Error('Disparo rechazado: el cuerpo no es JSON válido.');
}

return [{ json: cuerpo }];


// ── De dónde sale HMAC-SHA256 en este n8n ─────────────────────────────
// El sandbox del nodo Code de n8n Cloud NO expone `crypto` como variable
// global: usarlo tal cual da «crypto is not defined». Sí permite
// `require('crypto')`, que en Node 18+ trae `webcrypto` con la misma API.
//
// Se prueban las tres formas por orden, para que el flujo funcione igual en
// Cloud y en una instalación propia. Si no hay ninguna, se dice qué falta en
// vez de reventar con un error del motor.
function obtenerCripto() {
  if (typeof crypto !== 'undefined' && crypto && crypto.subtle) return crypto;
  if (typeof globalThis !== 'undefined' && globalThis.crypto && globalThis.crypto.subtle) {
    return globalThis.crypto;
  }
  try {
    const modulo = require('crypto');
    if (modulo && modulo.webcrypto && modulo.webcrypto.subtle) return modulo.webcrypto;
    if (modulo && modulo.subtle) return modulo;
  } catch (e) {
    // Sin permiso para require: se cae al error de abajo.
  }
  throw new Error(
    'Este n8n no ofrece HMAC-SHA256 en el nodo Code: no hay `crypto` global ni ' +
      'se permite require("crypto"). En una instalación propia se habilita con ' +
      'NODE_FUNCTION_ALLOW_BUILTIN=crypto.',
  );
}

// Preparar contexto
//
// Unifica los dos disparadores en una sola forma. La diferencia:
//
//   · Manual  → la aplicación YA creó la fila de automation_runs y manda su
//               run_id. Ese run_id es el cerrojo del límite de 10 minutos.
//   · Cron    → no hay nadie que la haya creado, así que se genera aquí un
//               run_id y el endpoint digest-payload crea la fila si no existe
//               (TECHNICAL_SPEC §9).

const cripto = obtenerCripto();

const entrada = $input.first()?.json ?? {};
const cuerpo = entrada.body ?? entrada;

const esManual = typeof cuerpo.run_id === 'string' && cuerpo.run_id.length > 0;

return [{
  json: {
    run_id: esManual ? cuerpo.run_id : cripto.randomUUID(),
    flow: 'morning_digest',
    trigger: esManual ? 'manual' : 'scheduled',
  },
}];

// ── De dónde sale HMAC-SHA256 en este n8n ─────────────────────────────
// El sandbox del nodo Code de n8n Cloud NO expone `crypto` como variable
// global: usarlo tal cual da «crypto is not defined». Sí permite
// `require('crypto')`, que en Node 18+ trae `webcrypto` con la misma API.
//
// Se prueban las tres formas por orden, para que el flujo funcione igual en
// Cloud y en una instalación propia. Si no hay ninguna, se dice qué falta en
// vez de reventar con un error del motor.
function obtenerCripto() {
  if (typeof crypto !== 'undefined' && crypto && crypto.subtle) return crypto;
  if (typeof globalThis !== 'undefined' && globalThis.crypto && globalThis.crypto.subtle) {
    return globalThis.crypto;
  }
  try {
    const modulo = require('crypto');
    if (modulo && modulo.webcrypto && modulo.webcrypto.subtle) return modulo.webcrypto;
    if (modulo && modulo.subtle) return modulo;
  } catch (e) {
    // Sin permiso para require: se cae al error de abajo.
  }
  throw new Error(
    'Este n8n no ofrece HMAC-SHA256 en el nodo Code: no hay `crypto` global ni ' +
      'se permite require("crypto"). En una instalación propia se habilita con ' +
      'NODE_FUNCTION_ALLOW_BUILTIN=crypto.',
  );
}

// Firmar la petición de datos
//
// Cadena que se firma:  `${timestamp}.${nonce}.${cuerpoCrudo}`
// Para el GET de digest-payload el cuerpo es la CADENA VACÍA
// (TECHNICAL_SPEC §8, «Contratos de los endpoints de n8n»).
//
// Se usa Web Crypto (cripto.subtle), que existe como global en Node 18+ y
// funciona en n8n Cloud sin habilitar módulos extra.

const cripto = obtenerCripto();

const secreto = $vars.N8N_SHARED_SECRET;
const base    = $vars.APP_BASE_URL;

if (!secreto) throw new Error('Falta la variable N8N_SHARED_SECRET en n8n (Settings → Variables).');
if (!base)    throw new Error('Falta la variable APP_BASE_URL en n8n (Settings → Variables).');

const { run_id, flow, trigger } = $input.first().json;

const timestamp = String(Math.floor(Date.now() / 1000));
const nonce     = cripto.randomUUID();
const cuerpo    = '';

const codificador = new TextEncoder();
const clave = await cripto.subtle.importKey(
  'raw',
  codificador.encode(secreto),
  { name: 'HMAC', hash: 'SHA-256' },
  false,
  ['sign'],
);
const firma = await cripto.subtle.sign(
  'HMAC',
  clave,
  codificador.encode(`${timestamp}.${nonce}.${cuerpo}`),
);
const hex = [...new Uint8Array(firma)].map((b) => b.toString(16).padStart(2, '0')).join('');

return [{
  json: {
    run_id,
    flow,
    trigger,
    url: `${base.replace(/\/$/, '')}/api/n8n/digest-payload?run_id=${encodeURIComponent(run_id)}&trigger=${encodeURIComponent(trigger)}`,
    timestamp,
    nonce,
    signature: `sha256=${hex}`,
  },
}];

