// El sandbox del nodo Code de n8n Cloud NO expone `crypto` como variable
// global: usarlo tal cual da «crypto is not defined». Sí permite
// `require('crypto')`, que en Node 18+ trae `webcrypto` con la misma API.
//
// Se prueban las tres formas por orden, para que el flujo funcione igual en
// Cloud y en una instalación propia. Si no hay ninguna, se dice qué falta en
// vez de reventar con un error del motor.
function obtenerCripto() {
  if (typeof crypto !== 'undefined' && crypto && crypto.subtle) return crypto;
  if (typeof globalThis !== 'undefined' && globalThis.crypto && globalThis.crypto.subtle) {
    return globalThis.crypto;
  }
