  'HMAC', clave, codificador.encode(`${timestamp}.${nonce}.${cuerpo}`),
);
const hex = [...new Uint8Array(firma)].map((b) => b.toString(16).padStart(2, '0')).join('');

return [{
  json: {
    url: `${base.replace(/\/$/, '')}/api/n8n/digest-result`,
    cuerpo,
    timestamp,
    nonce,
    signature: `sha256=${hex}`,
  },
}];

